/* p8 — a Tibetan family in Waco: Tenzin Dorje (father, weekend momo stand), Dolma (mother, thangka painter),
   Tsering Lhamo (daughter, Baylor student), Grandpa Lobsang (former monk). One family who ended up in Waco after the
   1990s resettlement — a story about exile, memory and making a home; the deepest echo of saudade in the game.
   One new Waco location (the family's yard + market stand), four 3-stage arcs (one stage per visit), butter tea,
   a Losar event (W35–37, Tibetan New Year), festival help (W46 d1 s1 → c4_fs), one ending paragraph.
   Flags: S.flags.p8_<name> (stage), p8_<name>V (visit count when last advanced), p8_tenzinFest / p8_dolmaFest /
   p8_tseringFest / p8_lobsangFest, p8_painting (Dolma's picture hangs in the shop), p8_losar 'went'|'tarts'|'call'. */
Object.assign(NPCS,{
 p8_tenzin:{n:['丹增·多吉','Tenzin Dorje','Tenzin Dorje'],s:['丹增','Tenzin','Tenzin'],p:['他','him','ele'],role:['韦科的藏族父亲，上夜班，周末在市集卖馍馍','Tibetan father in Waco: night shifts, momos at the weekend market','Pai tibetano em Waco: turnos da noite, momos na feira ao fim de semana'],loc:'waco'},
 p8_dolma:{n:['卓玛','Dolma','Dolma'],s:['卓玛','Dolma','Dolma'],p:['她','her','ela'],role:['丹增的妻子，唐卡画师，在社区中心教画','Tenzin\'s wife, a thangka painter who teaches at the community centre','Mulher do Tenzin, pintora de thangkas, dá aulas no centro comunitário'],loc:'waco'},
 p8_tsering:{n:['次仁·拉姆','Tsering Lhamo','Tsering Lhamo'],s:['次仁','Tsering','Tsering'],p:['她','her','ela'],role:['丹增的女儿，二十岁，贝勒大学新闻系学生','Tenzin\'s daughter, twenty, journalism student at Baylor','Filha do Tenzin, vinte anos, estudante de jornalismo em Baylor'],loc:'waco'},
 p8_lobsang:{n:['洛桑爷爷','Grandpa Lobsang','Avô Lobsang'],s:['洛桑爷爷','Grandpa Lobsang','o avô Lobsang'],p:['他','him','ele'],role:['丹增的父亲，八十多岁，年轻时出家，后来还俗成家','Tenzin\'s father, in his eighties; a monk as a young man who left to raise a family','Pai do Tenzin, oitenta e tal anos; foi monge em novo e deixou o mosteiro para criar família'],loc:'waco'}
});

(function(){
const ST=k=>S.flags['p8_'+k]||0;
const DAY=()=>typeof dayIndex==='function'?dayIndex():S.week*7+S.day;
const MET=id=>!!(S.npc[id]&&S.npc[id].met);
const sc=(title,meta,text,choices)=>({title,meta,text,choices});
const out=(text,sum)=>()=>say('',text,sum);
const STAGE=(id,n,m)=>t(`${res(tt(NPCS[id].n),'zh')} · 第 ${n}/${m} 段`,`${res(tt(NPCS[id].n),'en')} · part ${n}/${m}`,`${res(tt(NPCS[id].n),'pt')} · parte ${n}/${m}`);
const WACO=t('韦科','Waco','Waco');
// one stage per visit to Waco, each stage from a minimum week; after the arc, one chat a day
function arc(k,name,tip,weeks,stages,lines){const id='p8_'+k;return {id:'p8_'+k,n:name,cost:2,tip,
 req:()=>{const s=ST(k);
  if(s>=stages.length)return S.flags['p8_'+k+'C']===DAY()?t('今天已经聊过了','Already talked today','Já conversaram hoje'):true;
  if(S.week<weeks[s])return t(`第 ${weeks[s]} 周以后再来`,`Come back after week ${weeks[s]}`,`Volta depois da semana ${weeks[s]}`);
  return S.flags['p8_'+k+'V']!==(S.visited.waco||0)||t(`这一趟已经见过${res(tt(NPCS[id].s),'zh')}了，下次来韦科再接着聊`,`You've already seen ${res(tt(NPCS[id].s),'en')} this trip; the next part waits for your next visit to Waco`,`Já estiveste com ${res(tt(NPCS[id].s),'pt')} nesta viagem; o resto fica para a próxima visita a Waco`)},
 run:()=>{const s=ST(k);rel(id).met=true;
  if(s>=stages.length){S.flags['p8_'+k+'C']=DAY();addLike(id,0.5);const L=pick(lines);if(L[1])L[1]();return say(NM(id),L[0],L[2])}
  S.flags['p8_'+k]=s+1;S.flags['p8_'+k+'V']=S.visited.waco||0;const scn=stages[s]();scn.meta=STAGE(id,s+1,stages.length);return scn}}}
const SUM=(z,e,p)=>t(z,e,p);

/* ================= Tenzin Dorje — the momo stand ================= */
const tenzin=[
 ()=>sc(t('市集上的馍馍','Momos at the market','Momos na feira'),'',[
  t('韦科城边的周末市集，卖蜂蜜的、卖山核桃的、卖手工肥皂的。最里面一个摊位冒着白汽：一摞铝蒸笼，一块手写的牌子，上面是英文，下面是一行你看不懂的、弯弯的字。','The weekend market at the edge of Waco: honey, pecans, handmade soap. At the far end one stall is steaming: a stack of aluminium steamers and a hand-lettered sign, English on top and, underneath, a line of curling script you can\'t read.','A feira de fim de semana à saída de Waco: mel, nozes-pecã, sabonetes artesanais. Lá ao fundo, uma banca a fumegar: uma pilha de cestos de vapor de alumínio e uma tabuleta escrita à mão, em inglês por cima e, por baixo, uma linha de letras encaracoladas que não sabes ler.'),
  t('卖馍馍的男人五十多岁，眼睛熬得通红。他看了一眼你手背上的烫伤：“开店的？”“烧烤店。”“那你知道。”他递给你一个刚出笼的馍馍，“我叫丹增。牌子上那行是藏文，写的是‘家里的味道’。”','The man selling momos is in his fifties, eyes red from lack of sleep. He glances at the burns on the back of your hand. "Restaurant?" "A grill." "Then you know." He hands you a momo straight from the steamer. "I\'m Tenzin. That line on the sign is Tibetan. It says \'the taste of home.\'"','O homem dos momos tem cinquenta e tal anos e os olhos vermelhos de pouco dormir. Olha para as queimaduras nas costas da tua mão. «Restaurante?» «Uma churrasqueira.» «Então sabes.» Dá-te um momo acabado de sair do vapor. «Sou o Tenzin. Aquela linha na tabuleta é tibetano. Diz "o sabor de casa".»')],[
  {t:t('下次带炸鳕鱼饼来跟他换','Promise to bring salt cod fritters next time and swap','Prometer trazer pastéis de bacalhau da próxima vez para trocar'),fx:()=>{addTrust('p8_tenzin',1);addLike('p8_tenzin',1);S.lusoThisWeek=true},
   next:out(t('他把你的炸鳕鱼饼和他的馍馍并排放在一张纸盘上，看了半天：“都是把想家的东西包起来，炸一炸，蒸一蒸，卖给不想家的人。”','He sets your fritters and his momos side by side on a paper plate and studies them. "Both of them wrap up the thing you miss, fry it or steam it, and sell it to people who don\'t miss anything."','Põe os teus pastéis e os momos dele lado a lado num prato de papel e fica a olhar. «Os dois embrulham aquilo de que temos saudades, fritam ou cozem a vapor, e vendem a quem não tem saudades de nada.»'),SUM('丹增信任 +1 · 好感 +1','Tenzin trust +1 · affection +1','Confiança do Tenzin +1 · afeto +1'))},
  {t:t('[手艺 30] 卷起袖子，帮他包五十个','[Craft 30] Roll up your sleeves and fold fifty with him','[Ofício 30] Arregaçar as mangas e fechar cinquenta com ele'),req:()=>S.stats.oficio>=30||NEED(t('手艺 30','Craft 30','Ofício 30')),fx:()=>{addTrust('p8_tenzin',2);stat('oficio',1)},
   next:out(t('你的褶子捏得太少，他的一个馍馍有十八道褶。“我妈说，少于十八道，馅会跑出来，福气也会跑出来。”你的第五十个，终于捏到了十八道。','Your pleats are too few; each of his momos has eighteen. "My mother said fewer than eighteen and the filling runs out — and the luck with it." Your fiftieth finally gets all eighteen.','As tuas pregas são poucas; cada momo dele tem dezoito. «A minha mãe dizia que com menos de dezoito o recheio foge — e a sorte com ele.» O teu quinquagésimo finalmente leva as dezoito.'),SUM('丹增信任 +2 · 手艺 +1','Tenzin trust +2 · Craft +1','Confiança do Tenzin +2 · Ofício +1'))},
  {t:t('问他那行字是谁写的','Ask who wrote the line on the sign','Perguntar quem escreveu a linha na tabuleta'),fx:()=>{addTrust('p8_tenzin',1);stat('saud',1)},
   next:out(t('“我爸写的。他的字比我好看。”丹增笑了一下，“他说英文那行是给客人看的，藏文那行是给我自己看的。站一天，看一眼，就不累了。”','"My father wrote it. His hand is better than mine." Tenzin smiles a little. "He says the English is for the customers and the Tibetan is for me. Stand here all day, look at it once, and you\'re not tired any more."','«Foi o meu pai. Tem melhor letra do que eu.» O Tenzin sorri um pouco. «Diz que o inglês é para os clientes e o tibetano é para mim. Passo aqui o dia, olho uma vez, e já não estou cansado.»'),SUM('丹增信任 +1 · 乡愁 +1','Tenzin trust +1 · Homesickness +1','Confiança do Tenzin +1 · Saudade +1'))}]),
 ()=>sc(t('两个夜班','Two night shifts','Dois turnos da noite'),'',[
  t('丹增平时在城东一家医院的洗衣房上夜班，周末出摊，一天只睡四个钟头。凌晨五点，他在收摊，手在抖。“你呢？你一个人怎么撑一家店？”','On weekdays Tenzin works nights in a hospital laundry across town; at weekends he runs the stand. Four hours of sleep a day. At five in the morning he\'s packing up, and his hands are shaking. "And you? How do you keep a whole restaurant going on your own?"','Durante a semana o Tenzin faz noites na lavandaria de um hospital do outro lado da cidade; ao fim de semana tem a banca. Quatro horas de sono por dia. Às cinco da manhã está a arrumar, e as mãos tremem-lhe. «E tu? Como aguentas um restaurante sozinho?»')],[
  {t:t('说实话：你一开始也撑不住，后来雇了人','Tell the truth: you couldn\'t either, at first — then you hired help','Dizer a verdade: ao princípio também não aguentavas — depois contrataste gente'),fx:()=>{addTrust('p8_tenzin',2)},
   next:out(t('“雇人。”他重复了一遍，好像这是个外语词。下个礼拜，你在他的摊位后面看见了次仁，她在收钱，一边收一边写作业。','"Hire help." He repeats it like a foreign word. The next week you see Tsering behind his stall, taking money with one hand and doing homework with the other.','«Contratar gente.» Repete como se fosse uma palavra estrangeira. Na semana seguinte vês a Tsering atrás da banca, a receber o dinheiro com uma mão e a fazer os trabalhos com a outra.'),SUM('丹增信任 +2','Tenzin trust +2','Confiança do Tenzin +2'))},
  {t:t('请他来圣鲁伊斯，在你店门口摆一天摊','Invite him to San Luís to sell for a day outside your shop','Convidá-lo a vir a San Luís vender um dia à porta do teu restaurante'),fx:()=>{addTrust('p8_tenzin',1);S.rep+=1;stat('tex',1)},
   next:out(t('那个礼拜六，卡车司机们排着队吃了三百个馍馍，管它叫“西藏的玉米粽”。丹增没有纠正，只是笑。','That Saturday the truckers line up for three hundred momos and call them "Tibetan tamales." Tenzin doesn\'t correct them. He just laughs.','Nesse sábado os camionistas fazem fila para trezentos momos e chamam-lhes «tamales tibetanos». O Tenzin não corrige. Só se ri.'),SUM('丹增信任 +1 · 口碑 +1 · 德州味 +1','Tenzin trust +1 · Reputation +1 · Texanness +1','Confiança do Tenzin +1 · Reputação +1 · Texanidade +1'))},
  {t:t('什么都不说，陪他在车里吃一碗面','Say nothing; eat a bowl of noodles with him in his car','Não dizer nada; comer uma tigela de massa com ele no carro'),fx:()=>{addLike('p8_tenzin',1);stat('saud',1)},
   next:out(t('天亮之前的停车场，两个人，两碗泡面，一台开着暖气的旧车。谁也没说话。这样也算回答了。','A parking lot before dawn: two men, two cups of instant noodles, an old car with the heater on. Nobody talks. That counts as an answer too.','Um parque de estacionamento antes de amanhecer: dois homens, duas taças de massa instantânea, um carro velho com o aquecimento ligado. Ninguém fala. Também é uma resposta.'),SUM('丹增好感 +1 · 乡愁 +1','Tenzin affection +1 · Homesickness +1','Afeto do Tenzin +1 · Saudade +1'))}]),
 ()=>sc(t('一个没去过的地方','A place he\'s never been','Um sítio onde nunca esteve'),'',[
  t('丹增从钱包里拿出一张折得很旧的地图，不是西藏，是印度南方的卡纳塔克邦。“我在这里出生，拜拉库比，一个难民定居点。我爸妈是从山那边走过来的。我自己，一次也没见过那座山。”','Tenzin takes a much-folded map from his wallet. Not Tibet: Karnataka, in the south of India. "I was born here. Bylakuppe, a refugee settlement. My parents walked over from the other side of the mountains. Me, I\'ve never once seen those mountains."','O Tenzin tira da carteira um mapa muito dobrado. Não é o Tibete: é Karnataka, no sul da Índia. «Nasci aqui. Bylakuppe, um povoado de refugiados. Os meus pais vieram a pé do outro lado das montanhas. Eu nunca vi essas montanhas.»'),
  t('“九十年代，美国有个项目，接了一千个藏人过来。我二十出头，分到了德州。”他把地图叠回去，“你想你的里斯本。我想的，是一个我从来没去过的地方。”','"In the nineties there was a US programme that brought over a thousand Tibetans. I was in my early twenties and got sent to Texas." He folds the map away. "You miss your Lisbon. What I miss is a place I\'ve never been."','«Nos anos noventa houve um programa americano que trouxe mil tibetanos. Eu tinha vinte e poucos anos e calhou-me o Texas.» Volta a dobrar o mapa. «Tu tens saudades da tua Lisboa. Eu tenho saudades de um sítio onde nunca estive.»')],[
  {t:t('教他一个葡语词：思念','Teach him a Portuguese word: saudade','Ensinar-lhe uma palavra portuguesa: saudade'),fx:()=>{addTrust('p8_tenzin',2);stat('saud',2);S.lusoThisWeek=true},
   next:out(t('你解释了半天，说这个词想念的可以是一个人、一个地方，甚至是一个从来没有过的东西。丹增点点头：“那我们藏语里也有。只是我们不好意思说出来。”','You explain for a long time: the word can mean missing a person, a place, even something that never was. Tenzin nods. "Then we have it in Tibetan too. We\'re just too shy to say it out loud."','Explicas muito tempo: a palavra pode ser a falta de uma pessoa, de um sítio, até de uma coisa que nunca existiu. O Tenzin acena. «Então em tibetano também temos. Só temos vergonha de a dizer em voz alta.»'),SUM('丹增信任 +2 · 乡愁 +2','Tenzin trust +2 · Homesickness +2','Confiança do Tenzin +2 · Saudade +2'))},
  {t:t('讲若泽：一个二十多年没回家的人','Tell him about José, who didn\'t go home for twenty-some years','Falar-lhe do José, que passou mais de vinte anos sem voltar a casa'),fx:()=>{addTrust('p8_tenzin',2)},
   next:out(t('他听完，沉默了很久：“你舅舅不回去，是因为怕。我爸不回去，是因为回不去。我不回去，是因为不知道该回哪儿。”他想了想，“可我们都在德州开了个卖吃的地方。真奇怪。”','He listens and is quiet a long while. "Your uncle didn\'t go back because he was afraid. My father doesn\'t because he can\'t. I don\'t because I don\'t know where back would be." He thinks. "And all of us ended up selling food in Texas. Strange."','Ouve e fica muito tempo calado. «O teu tio não voltou porque tinha medo. O meu pai não volta porque não pode. Eu não volto porque não sei para onde seria voltar.» Pensa. «E acabámos todos a vender comida no Texas. Que estranho.»'),SUM('丹增信任 +2','Tenzin trust +2','Confiança do Tenzin +2'))},
  {t:t('请他圣安东尼节来摆一摊馍馍','Ask him to bring a momo stand to the Santo António festival','Pedir-lhe que leve uma banca de momos à festa de Santo António'),fx:()=>{addTrust('p8_tenzin',1);S.flags.p8_tenzinFest=1},
   next:out(t('“圣安东尼是谁？”“一个帮人找丢了的东西的圣人。”丹增笑了：“那我得去。我丢的东西有点多。”','"Who\'s Saint Anthony?" "A saint who helps people find what they\'ve lost." Tenzin laughs. "Then I\'d better come. I\'ve lost quite a lot."','«Quem é o Santo António?» «Um santo que ajuda a encontrar o que se perdeu.» O Tenzin ri-se. «Então tenho de ir. Perdi bastante coisa.»'),SUM('丹增会来圣安东尼节帮忙','Tenzin will help at the festival','O Tenzin vai ajudar na festa'))}])
];
const tenzinChat=[
 [t('丹增说下次要带一笼馍馍去吴家餐馆，跟美玲的饺子比一比。“她赢了也没关系，”他说，“我主要是想吃她的饺子。”','Tenzin says next time he\'ll take a steamer of momos to Wu\'s Kitchen and put them up against Meiling\'s dumplings. "If she wins, fine," he says. "Mostly I want to eat her dumplings."','O Tenzin diz que da próxima vez leva um cesto de momos à Cozinha Wu para competir com os pastéis da Meiling. «Se ela ganhar, tudo bem», diz. «No fundo, quero é comer os pastéis dela.»'),null,''],
 [t('他在给辣酱试新配方，辣得你眼泪直流。“太辣了？”“刚好。”“你骗人。”“刚好。”','He\'s testing a new chilli sauce, and it makes your eyes stream. "Too hot?" "Just right." "You\'re lying." "Just right."','Está a experimentar um molho picante novo que te faz chorar. «Picante de mais?» «No ponto.» «Mentiroso.» «No ponto.»'),()=>{stat('tex',1)},t('德州味 +1','Texanness +1','Texanidade +1')],
 [t('“这个礼拜卖了四百个，”他说，“比上个礼拜多五十个。我爸说，是因为你上次来的时候在摊前站了一会儿，人们以为这家很好吃。”','"Four hundred this week," he says. "Fifty more than last week. My father says it\'s because you stood at the stall for a while last time, and people thought it must be good."','«Quatrocentos esta semana», diz. «Mais cinquenta do que na anterior. O meu pai diz que é porque da última vez ficaste um bocado à frente da banca e as pessoas pensaram que devia ser bom.»'),()=>{S.rep+=0.5},'']
];

/* ================= Dolma — thangka painter ================= */
const dolma=[
 ()=>sc(t('一笔一个下午','One stroke an afternoon','Um traço por tarde'),'',[
  t('社区中心后面的一间小屋里，卓玛在教六个学生画唐卡。颜料是石头磨的：孔雀石的绿、朱砂的红，还有一小罐真的金粉。墙上挂着一幅没画完的佛像，只画了一只手。','In a small room behind the community centre, Dolma is teaching six students to paint thangkas. The pigments are ground from stone: malachite green, cinnabar red, and a tiny jar of real gold. On the wall hangs an unfinished figure, only one hand painted.','Numa salinha atrás do centro comunitário, a Dolma ensina seis alunos a pintar thangkas. Os pigmentos são moídos de pedra: verde de malaquite, vermelho de cinábrio e um frasquinho de ouro verdadeiro. Na parede, uma figura por acabar, só com uma mão pintada.'),
  t('“这只手画了三个礼拜，”她说，“我妈说，画快了，画里的人会不高兴。”','"That hand took three weeks," she says. "My mother said if you paint too fast, the person in the painting won\'t be happy."','«Essa mão levou três semanas», diz ela. «A minha mãe dizia que, se pintares depressa de mais, a pessoa do quadro não fica contente.»')],[
  {t:t('坐下来上一节课','Sit down and take a lesson','Sentar-te e ter uma aula'),fx:()=>{stat('oficio',1);stat('saud',1);addTrust('p8_dolma',1)},
   next:out(t('你画了一个下午，画出了一朵云。卓玛看了看：“云的边要再软一点。像你们烤肉时的烟。”','You paint all afternoon and manage one cloud. Dolma looks. "The edge of the cloud should be softer. Like the smoke off your grill."','Pintas a tarde inteira e consegues uma nuvem. A Dolma olha. «A borda da nuvem devia ser mais macia. Como o fumo da tua grelha.»'),SUM('手艺 +1 · 乡愁 +1 · 卓玛信任 +1','Craft +1 · Homesickness +1 · Dolma trust +1','Ofício +1 · Saudade +1 · confiança da Dolma +1'))},
  {t:t('问她墙上那幅画的是谁','Ask who the figure on the wall is','Perguntar quem é a figura na parede'),fx:()=>{addTrust('p8_dolma',1)},
   next:out(t('“绿度母。保护走远路的人。”她看了你一眼，“我画她，是给我女儿的。她每天开车去学校，三十分钟。在我眼里，那也是远路。”','"Green Tara. She protects people on long journeys." She glances at you. "I\'m painting her for my daughter. She drives thirty minutes to school every day. To me, that\'s a long journey too."','«Tara Verde. Protege quem faz viagens longas.» Olha para ti. «Estou a pintá-la para a minha filha. Conduz trinta minutos todos os dias para a universidade. Para mim também é uma viagem longa.»'),SUM('卓玛信任 +1','Dolma trust +1','Confiança da Dolma +1'))},
  {t:t('讲葡萄牙的瓷砖画：也是一笔一笔的蓝','Tell her about Portuguese azulejos: blue, one stroke at a time','Falar-lhe dos azulejos portugueses: azul, um traço de cada vez'),fx:()=>{stat('saud',2);addLike('p8_dolma',1);S.lusoThisWeek=true},
   next:out(t('她要你在手机上找给她看。看了很久：“你们画在墙上，让所有人路过的时候看。我们画在布上，卷起来，带着走。”她顿了顿，“因为我们要走。”','She has you find pictures on your phone and looks for a long time. "You paint on walls, for everyone who walks by. We paint on cloth so we can roll it up and carry it." A pause. "Because we have to leave."','Pede-te que lhe mostres fotografias no telemóvel e olha muito tempo. «Vocês pintam nas paredes, para quem passa. Nós pintamos em pano, para enrolar e levar.» Uma pausa. «Porque temos de partir.»'),SUM('乡愁 +2 · 卓玛好感 +1','Homesickness +2 · Dolma affection +1','Saudade +2 · afeto da Dolma +1'))}]),
 ()=>sc(t('蓝色从哪里来','Where blue comes from','De onde vem o azul'),'',[
  t('卓玛的青金石用完了。那种深蓝，她说，以前是从很远的山里一点一点运出来的。现在网上能买到，可是贵，她这个月的课钱不够。','Dolma has run out of lapis lazuli. That deep blue, she says, used to be carried bit by bit out of faraway mountains. You can buy it online now, but it\'s expensive, and this month\'s class fees won\'t cover it.','A Dolma ficou sem lápis-lazúli. Aquele azul profundo, diz, vinha aos bocadinhos de montanhas muito longe. Agora compra-se na internet, mas é caro, e as aulas deste mês não chegam.')],[
  {t:t('把店里一块若泽留下的旧瓷砖送给她','Give her one of José\'s old spare azulejos from the shop','Dar-lhe um dos azulejos velhos que o José deixou no restaurante'),fx:()=>{addTrust('p8_dolma',2);stat('saud',1)},
   next:out(t('她把瓷砖放在画桌正中，没有磨，也没有用。“这块不能磨，”她说，“这是别人的家。我照着它的蓝，调我的蓝。”','She sets the tile in the middle of her painting table and neither grinds it nor uses it. "I can\'t grind this one," she says. "It\'s someone else\'s home. I\'ll match my blue to its blue."','Põe o azulejo no meio da mesa de pintura e não o mói nem o usa. «Este não se mói», diz. «É a casa de outra pessoa. Vou acertar o meu azul pelo azul dele.»'),SUM('卓玛信任 +2 · 乡愁 +1','Dolma trust +2 · Homesickness +1','Confiança da Dolma +2 · Saudade +1'))},
  {t:t('[$60] 替她买下这个月的颜料','[$60] Pay for this month\'s pigment','[$60] Pagar o pigmento deste mês'),req:MONEY(60),fx:()=>{S.cash-=60;addTrust('p8_dolma',1);addLike('p8_dolma',1)},
   next:out(t('她不肯收，最后收下了，条件是你也得来上一节课，画完那朵云。','She refuses, then accepts on one condition: you come to another lesson and finish that cloud.','Recusa, depois aceita com uma condição: vens a mais uma aula e acabas a nuvem.'),SUM('卓玛信任 +1 · 好感 +1 · −$60','Dolma trust +1 · affection +1 · −$60','Confiança da Dolma +1 · afeto +1 · −$60'))},
  {t:t('听她讲在达兰萨拉学画的日子','Listen to her talk about learning to paint in Dharamsala','Ouvi-la falar de quando aprendeu a pintar em Dharamsala'),fx:()=>{addTrust('p8_dolma',2)},
   next:out(t('“十二岁，我妈把我送去学画。早上五点起来磨颜料，磨一个钟头，手是绿的，吃饭也是绿的。”她笑了，“现在我教美国学生，他们磨十分钟就问能不能用管装的。”','"At twelve my mother sent me to learn. Up at five to grind pigment for an hour — green hands, green breakfast." She laughs. "Now I teach American students, and after ten minutes of grinding they ask if they can use tubes."','«Aos doze anos a minha mãe mandou-me aprender. Levantar às cinco para moer pigmento uma hora — mãos verdes, pequeno-almoço verde.» Ri-se. «Agora ensino alunos americanos, e ao fim de dez minutos perguntam se podem usar tubos.»'),SUM('卓玛信任 +2','Dolma trust +2','Confiança da Dolma +2'))}]),
 ()=>sc(t('给店里的画','A painting for the shop','Um quadro para o restaurante'),'',[
  t('卓玛递给你一个用旧报纸包着的小画框。打开：一条银色的沙丁鱼，游在一座雪山的倒影里，边上画着一圈葡萄牙蓝的花纹。','Dolma hands you a small frame wrapped in old newspaper. Inside: a silver sardine swimming through the reflection of a snow mountain, edged with a border of Portuguese blue.','A Dolma dá-te um pequeno quadro embrulhado em jornal velho. Lá dentro: uma sardinha prateada a nadar no reflexo de uma montanha nevada, com uma cercadura de azul português.'),
  t('“你的鱼，我的山，”她说，“挂在店里。客人看鱼，你看山。”','"Your fish, my mountain," she says. "Hang it in the shop. The customers look at the fish. You look at the mountain."','«O teu peixe, a minha montanha», diz. «Pendura-o no restaurante. Os clientes olham para o peixe. Tu olhas para a montanha.»')],[
  {t:t('挂在店门口，进门第一眼就能看见','Hang it by the door, the first thing anyone sees','Pendurá-lo à porta, a primeira coisa que se vê'),fx:()=>{if(!S.flags.p8_painting){S.flags.p8_painting=1;S.rep+=2;log('卓玛画的沙丁鱼和雪山挂在了店门口','Dolma\'s painting of a sardine and a snow mountain now hangs by the shop door','O quadro da Dolma com uma sardinha e uma montanha nevada está agora à porta do restaurante')}addTrust('p8_dolma',1)},
   next:out(t('第一个礼拜就有三个客人问能不能买。你说不卖。阿尔贝蒂娜太太站在画前面看了很久，说那座山像亚速尔的皮库山，只是更白。','In the first week three customers ask to buy it. You say it\'s not for sale. Dona Albertina stands in front of it a long time and says the mountain looks like Pico in the Azores, only whiter.','Na primeira semana três clientes perguntam se o podem comprar. Dizes que não está à venda. A Dona Albertina fica muito tempo à frente dele e diz que a montanha parece o Pico, nos Açores, só que mais branca.'),SUM('口碑 +2 · 卓玛信任 +1','Reputation +2 · Dolma trust +1','Reputação +2 · confiança da Dolma +1'))},
  {t:t('请她为圣安东尼节画一面幡','Ask her to paint a banner for the Santo António festival','Pedir-lhe que pinte um estandarte para a festa de Santo António'),fx:()=>{if(!S.flags.p8_painting){S.flags.p8_painting=1;S.rep+=2;log('卓玛画的沙丁鱼和雪山挂在了店门口','Dolma\'s painting of a sardine and a snow mountain now hangs by the shop door','O quadro da Dolma com uma sardinha e uma montanha nevada está agora à porta do restaurante')}S.flags.p8_dolmaFest=1},
   next:out(t('“一个葡萄牙的圣人，”她想了想，“我不会画他的脸。我画他手里的东西：一本书，一个孩子，一株罗勒。”','"A Portuguese saint." She thinks. "I don\'t know how to paint his face. I\'ll paint what he holds: a book, a child, a pot of basil."','«Um santo português.» Pensa. «Não sei pintar a cara dele. Pinto o que ele segura: um livro, uma criança, um manjerico.»'),SUM('卓玛会为圣安东尼节画幡 · 口碑 +2','Dolma will paint a festival banner · Reputation +2','A Dolma vai pintar um estandarte para a festa · Reputação +2'))},
  {t:t('“这太贵重了。”','"This is too precious."','«Isto é valioso de mais.»'),fx:()=>{addTrust('p8_dolma',1);stat('saud',1)},
   next:out(t('“画不贵重，”她说，“画画的三个礼拜贵重。所以你要收下，不然那三个礼拜就没地方去了。”你收下了，挂在楼上你的小房间里。','"The painting isn\'t precious," she says. "The three weeks are. So you have to take it, or those three weeks have nowhere to go." You take it, and hang it in your little room upstairs.','«O quadro não é valioso», diz. «As três semanas é que são. Por isso tens de o aceitar, senão essas três semanas não têm para onde ir.» Aceitas, e penduras no teu quartinho lá em cima.'),SUM('卓玛信任 +1 · 乡愁 +1','Dolma trust +1 · Homesickness +1','Confiança da Dolma +1 · Saudade +1'))}])
];
const dolmaChat=[
 [t('卓玛在给一个学生改画，改的是一片叶子，改了半个钟头。学生想哭，她想笑。','Dolma is correcting a student\'s painting — one leaf, for half an hour. The student wants to cry; Dolma wants to laugh.','A Dolma está a corrigir o quadro de um aluno — uma folha, durante meia hora. O aluno quer chorar; a Dolma quer rir.'),null,''],
 [t('“你瘦了，”她说，“开店的人都瘦。我画佛像都画得胖胖的，就是因为我们家的人都太瘦了。”','"You\'ve lost weight," she says. "Restaurant people are always thin. I paint my figures nice and round because everyone in our family is too thin."','«Emagreceste», diz. «A gente dos restaurantes é sempre magra. Pinto as minhas figuras bem redondinhas porque na nossa família estão todos magros de mais.»'),()=>{stat('saud',1)},t('乡愁 +1','Homesickness +1','Saudade +1')]
];

/* ================= Tsering Lhamo — Baylor journalism student ================= */
const tsering=[
 ()=>sc(t('三种口音','Three accents','Três sotaques'),'',[
  t('丹增的女儿次仁二十岁，贝勒大学新闻系，说话是地道的德州口音，在家说藏语，高中学的西班牙语还记得一半。她在做一个课堂作业：采访“在德州开小吃店的外来人”。','Tenzin\'s daughter Tsering is twenty, a journalism student at Baylor. She talks pure Texan, speaks Tibetan at home and still has half her high-school Spanish. She\'s doing a class assignment: interviewing "outsiders running food businesses in Texas."','A filha do Tenzin, a Tsering, tem vinte anos e estuda jornalismo em Baylor. Fala texano puro, tibetano em casa e ainda tem meio espanhol do liceu. Está a fazer um trabalho para uma cadeira: entrevistar «forasteiros com negócios de comida no Texas».'),
  t('她打开手机录音：“第一个问题。你觉得你是外来人吗？”','She starts recording on her phone. "First question. Do you think of yourself as an outsider?"','Começa a gravar no telemóvel. «Primeira pergunta. Consideras-te um forasteiro?»')],[
  {t:t('说实话：每天早上是，晚上打烊的时候不是','Tell the truth: every morning yes, by closing time no','Dizer a verdade: todas as manhãs sim, à hora de fechar não'),fx:()=>{addTrust('p8_tsering',2)},
   next:out(t('她停下录音，看了你一会儿：“这个我能直接用吗？我爸也是这样，只是他从来不说。”','She stops the recording and looks at you. "Can I use that word for word? My dad\'s the same. He just never says it."','Para a gravação e olha para ti. «Posso usar isso tal e qual? O meu pai é igual. Só que nunca o diz.»'),SUM('次仁信任 +2','Tsering trust +2','Confiança da Tsering +2'))},
  {t:t('[魅力 45] 把采访变成一场脱口秀','[Charm 45] Turn the interview into a stand-up set','[Charme 45] Transformar a entrevista num número de comédia'),req:CHARM_REQ(45),fx:()=>{addLike('p8_tsering',2);S.online=clamp(S.online+2,0,100)},
   next:out(t('她的同学们把录音放了三遍，笑了三遍。教授给她的评语是：“受访者很有魅力，但你问得不够深。”她说下次要问得深一点。','Her classmates play the recording three times and laugh three times. The professor\'s note says: "Charming interviewee, but you didn\'t dig deep enough." She says next time she\'ll dig.','Os colegas ouvem a gravação três vezes e riem-se três vezes. O comentário do professor: «Entrevistado encantador, mas não foste fundo o suficiente.» Ela diz que para a próxima vai mais fundo.'),SUM('次仁好感 +2 · 线上评分 +2','Tsering affection +2 · online rating +2','Afeto da Tsering +2 · avaliação online +2'))},
  {t:t('反过来问她：“那你呢？”','Turn it round: "What about you?"','Inverter a pergunta: «E tu?»'),fx:()=>{addTrust('p8_tsering',1);stat('tex',1)},
   next:out(t('“我在德州出生的。”她停了一下，“可是填表的时候，‘出生地’和‘民族’那两栏，我永远要多想两秒钟。”','"I was born in Texas." She pauses. "But on forms, the boxes for \'place of birth\' and \'ethnicity\' — I always need two extra seconds."','«Nasci no Texas.» Faz uma pausa. «Mas nos formulários, os quadradinhos de "local de nascimento" e "etnia" — preciso sempre de mais dois segundos.»'),SUM('次仁信任 +1 · 德州味 +1','Tsering trust +1 · Texanness +1','Confiança da Tsering +1 · Texanidade +1'))}]),
 ()=>sc(t('家里的语言','The language at home','A língua de casa'),'',[
  t('次仁说，爷爷跟她讲话只用藏语，她全听得懂，可回答的时候总是用英语。“我的藏语像一件小时候的衣服，穿不上了，又舍不得扔。”','Tsering says her grandfather only ever speaks to her in Tibetan. She understands every word, but always answers in English. "My Tibetan is like a childhood coat. Doesn\'t fit any more, and I can\'t bring myself to throw it out."','A Tsering diz que o avô só lhe fala em tibetano. Ela percebe tudo, mas responde sempre em inglês. «O meu tibetano é como um casaco de criança. Já não me serve, e não tenho coragem de o deitar fora.»')],[
  {t:t('讲比·梅洛：四十岁才开始学外婆的语言','Tell her about Bea Melo, who started learning her grandmother\'s language at forty','Falar-lhe da Bea Melo, que começou a aprender a língua da avó aos quarenta'),fx:()=>{addTrust('p8_tsering',2)},
   next:out(t('“四十岁？”她算了算，“那我还有二十年。”然后她笑了，“不对，爷爷没有二十年了。”那天晚上，她第一次用藏语回答了爷爷。','"Forty?" She does the maths. "Then I\'ve got twenty years." Then she laughs. "No — Grandpa hasn\'t got twenty years." That night, for the first time, she answers her grandfather in Tibetan.','«Quarenta?» Faz as contas. «Então tenho vinte anos.» Depois ri-se. «Não — o avô não tem vinte anos.» Nessa noite, pela primeira vez, responde ao avô em tibetano.'),SUM('次仁信任 +2','Tsering trust +2','Confiança da Tsering +2'))},
  {t:t('劝她把爷爷讲的故事录下来','Tell her to record her grandfather\'s stories','Aconselhá-la a gravar as histórias do avô'),fx:()=>{addTrust('p8_tsering',1);addTrust('p8_lobsang',1)},
   next:out(t('她用做作业的那支麦克风录了一个礼拜。爷爷一开始不肯说，后来停不下来。她说她终于知道了自己的名字是谁起的。','She records for a week with the same microphone she uses for class. At first her grandfather won\'t talk; then he can\'t stop. She says she finally knows who chose her name.','Grava durante uma semana com o mesmo microfone das aulas. Ao princípio o avô não quer falar; depois não consegue parar. Diz que finalmente sabe quem lhe escolheu o nome.'),SUM('次仁信任 +1 · 洛桑爷爷信任 +1','Tsering trust +1 · Grandpa Lobsang trust +1','Confiança da Tsering +1 · confiança do avô Lobsang +1'))},
  {t:t('[德州味 40] “当德州人，也是一种回家。”','[Texanness 40] "Being Texan is a way of coming home too."','[Texanidade 40] «Ser texano também é uma maneira de voltar a casa.»'),req:()=>S.stats.tex>=40||NEED(t('德州味 40','Texanness 40','Texanidade 40')),fx:()=>{addLike('p8_tsering',1);stat('tex',1)},
   next:out(t('“你说得容易，”她说，“你是选择来的。”然后她叹了口气，“可你说得也对。我两个都要，不行吗？”“行。”','"Easy for you to say," she says. "You chose to come." Then she sighs. "But you\'re right too. Can\'t I have both?" "You can."','«Para ti é fácil dizer», responde. «Tu escolheste vir.» Depois suspira. «Mas também tens razão. Não posso ter as duas coisas?» «Podes.»'),SUM('次仁好感 +1 · 德州味 +1','Tsering affection +1 · Texanness +1','Afeto da Tsering +1 · Texanidade +1'))}]),
 ()=>sc(t('毕业专题','The capstone','O projeto final'),'',[
  t('次仁的毕业专题定了：写一家人，从山那边走到印度，再从印度飞到德州。她想用你的店做开头：“一个葡萄牙人在德州卖烤沙丁鱼，让我第一次想写我们家。”','Tsering has chosen her capstone: a family that walked from beyond the mountains to India, then flew from India to Texas. She wants to open with your shop: "A Portuguese man selling grilled sardines in Texas made me want to write about my family for the first time."','A Tsering escolheu o projeto final: uma família que veio a pé do outro lado das montanhas até à Índia e depois voou da Índia para o Texas. Quer começar pelo teu restaurante: «Um português a vender sardinhas assadas no Texas fez-me querer escrever pela primeira vez sobre a minha família.»')],[
  {t:t('介绍她认识科琳','Introduce her to Colleen','Apresentá-la à Colleen'),req:()=>rel('colleen').met||NEED(t('认识科琳','Know Colleen','Conhecer a Colleen')),fx:()=>{addTrust('p8_tsering',2);addTrust('colleen',1)},
   next:out(t('科琳看完她的稿子，删掉了一半形容词，留下了所有的名字。“名字是最难写的，”她说，“你写对了。”','Colleen reads her draft, cuts half the adjectives and keeps every name. "Names are the hardest thing to write," she says. "You got them right."','A Colleen lê o rascunho, corta metade dos adjetivos e mantém todos os nomes. «Os nomes são o mais difícil de escrever», diz. «Acertaste.»'),SUM('次仁信任 +2 · 科琳信任 +1','Tsering trust +2 · Colleen trust +1','Confiança da Tsering +2 · confiança da Colleen +1'))},
  {t:t('“别用我开头。用你爷爷。”','"Don\'t open with me. Open with your grandfather."','«Não comeces por mim. Começa pelo teu avô.»'),fx:()=>{addTrust('p8_tsering',2);addTrust('p8_lobsang',1)},
   next:out(t('她改了。第一句变成：“我爷爷十九岁那年，翻过了一座他再也没见过的山。”','She changes it. The first line becomes: "When my grandfather was nineteen, he crossed a mountain he never saw again."','Muda. A primeira frase passa a ser: «Quando o meu avô tinha dezanove anos, atravessou uma montanha que nunca mais voltou a ver.»'),SUM('次仁信任 +2 · 洛桑爷爷信任 +1','Tsering trust +2 · Grandpa Lobsang trust +1','Confiança da Tsering +2 · confiança do avô Lobsang +1'))},
  {t:t('请她来拍圣安东尼节，做专题的结尾','Ask her to photograph the Santo António festival as the ending','Pedir-lhe que fotografe a festa de Santo António para o final'),fx:()=>{addTrust('p8_tsering',1);S.flags.p8_tseringFest=1},
   next:out(t('“一个葡萄牙的节，在德州，藏族人来拍。”她笑了，“我的教授会觉得我编的。”','"A Portuguese festival, in Texas, photographed by a Tibetan." She laughs. "My professor will think I made it up."','«Uma festa portuguesa, no Texas, fotografada por uma tibetana.» Ri-se. «O meu professor vai achar que inventei.»'),SUM('次仁会来圣安东尼节帮忙','Tsering will help at the festival','A Tsering vai ajudar na festa'))}])
];
const tseringChat=[
 [t('次仁在复习统计学，嘴里念的是英语，草稿纸边上写的是藏文。','Tsering is revising statistics, muttering in English, with Tibetan scribbled in the margins of her scratch paper.','A Tsering está a estudar estatística, a resmungar em inglês, com tibetano rabiscado nas margens do papel.'),null,''],
 [t('“我同学问我是不是中国人，”她说，“我说我是德州人。他说那你父母呢？我说他们是韦科人。他放弃了。”','"A classmate asked if I was Chinese," she says. "I said I\'m Texan. He said, what about your parents? I said they\'re from Waco. He gave up."','«Um colega perguntou-me se eu era chinesa», diz. «Disse que sou texana. Ele perguntou: e os teus pais? Disse que são de Waco. Desistiu.»'),()=>{stat('tex',1)},t('德州味 +1','Texanness +1','Texanidade +1')]
];

/* ================= Grandpa Lobsang — butter tea and the prayer wheel ================= */
const lobsang=[
 ()=>sc(t('酥油茶','Butter tea','Chá de manteiga'),'',[
  t('院子里，一个八十多岁的老人坐在塑料椅上，手里转着一个小小的转经筒，转一圈，嘴里念一句。他看见你，什么也没说，进屋端出来一碗茶。','In the yard an old man in his eighties sits on a plastic chair, turning a small prayer wheel: one turn, one murmured line. He sees you, says nothing, goes inside and comes back with a bowl of tea.','No quintal, um velho de oitenta e tal anos está sentado numa cadeira de plástico a girar uma pequena roda de oração: uma volta, uma frase murmurada. Vê-te, não diz nada, entra em casa e volta com uma tigela de chá.'),
  t('是咸的，上面浮着一层黄油。你喝了一口，表情没管住。老人不出声地笑了，笑得肩膀一抖一抖。','It\'s salty, with a layer of butter floating on top. You take a sip and your face gives you away. The old man laughs without a sound, his shoulders shaking.','É salgado, com uma camada de manteiga a boiar. Bebes um gole e a cara denuncia-te. O velho ri-se sem som, com os ombros a tremer.')],[
  {t:t('把一整碗喝完','Drink the whole bowl','Beber a tigela toda'),fx:()=>{addTrust('p8_lobsang',2);stat('tex',1)},
   next:out(t('他又给你倒满了。丹增后来告诉你，在他们家，喝完第一碗就得接着喝第二碗，这叫礼貌。你喝了三碗。','He fills it up again. Later Tenzin tells you that in their family, finishing the first bowl means you get a second: that\'s manners. You drink three.','Volta a enchê-la. Mais tarde o Tenzin explica-te que, na família deles, acabar a primeira tigela quer dizer que vem a segunda: é a boa educação. Bebes três.'),SUM('洛桑爷爷信任 +2 · 德州味 +1','Grandpa Lobsang trust +2 · Texanness +1','Confiança do avô Lobsang +2 · Texanidade +1'))},
  {t:t('下次给他带一杯葡萄牙咖啡','Bring him a Portuguese coffee next time','Trazer-lhe um café português da próxima vez'),fx:()=>{addLike('p8_lobsang',1);S.lusoThisWeek=true},
   next:out(t('他喝了你带来的浓缩咖啡，皱着眉想了很久，然后往里面加了一小块黄油。“现在好了。”这是他对你说的第一句英语。','He drinks the espresso you brought, frowns a long time, then drops in a small knob of butter. "Now it\'s good." It\'s the first thing he\'s said to you in English.','Bebe o café que trouxeste, franze a testa muito tempo e depois põe-lhe um bocadinho de manteiga. «Agora está bom.» É a primeira coisa que te diz em inglês.'),SUM('洛桑爷爷好感 +1','Grandpa Lobsang affection +1','Afeto do avô Lobsang +1'))},
  {t:t('坐在他旁边，看他转经筒','Sit beside him and watch the prayer wheel turn','Sentar-te ao lado dele e ver a roda girar'),fx:()=>{stat('saud',2);addTrust('p8_lobsang',1)},
   next:out(t('转经筒一圈一圈地转。韦科的风吹过院子里的山核桃树。你忽然想起阿尔法马的外婆，也是这样坐在门口，一颗一颗地数念珠。','The wheel turns and turns. The Waco wind moves through the pecan tree in the yard. Suddenly you think of your grandmother in Alfama, sitting in her doorway just like this, counting rosary beads one by one.','A roda gira e gira. O vento de Waco passa pela nogueira-pecã do quintal. De repente lembras-te da tua avó em Alfama, sentada à porta assim mesmo, a passar as contas do terço uma a uma.'),SUM('乡愁 +2 · 洛桑爷爷信任 +1','Homesickness +2 · Grandpa Lobsang trust +1','Saudade +2 · confiança do avô Lobsang +1'))}]),
 ()=>sc(t('两座山','Two mountains','Duas montanhas'),'',[
  t('次仁在旁边翻译。洛桑爷爷说，他十九岁那年，从寺院里出来，跟着很多人一起翻过了雪山，走到了印度。后来还了俗，娶了妻，有了丹增。','Tsering translates. Grandpa Lobsang says that when he was nineteen he left his monastery and crossed the snow mountains with many others, walking all the way to India. Later he left the robes, married, and had Tenzin.','A Tsering traduz. O avô Lobsang conta que aos dezanove anos saiu do mosteiro e atravessou as montanhas nevadas com muitos outros, a pé até à Índia. Mais tarde deixou o hábito, casou e teve o Tenzin.'),
  t('“走的时候，回头看了一眼那座山。就那一眼。”他用手比了一个很高的样子，“后来在印度，在德州，看见的山都太矮了。”','"When we left, I looked back at the mountain once. Only once." He holds his hand up very high. "Afterwards, in India, in Texas, every mountain I saw was too low."','«Quando partimos, olhei uma vez para trás, para a montanha. Só uma vez.» Levanta a mão muito alto. «Depois, na Índia, no Texas, todas as montanhas que vi eram baixas de mais.»')],[
  {t:t('讲阿尔法马的山坡：也是回头看了一眼','Tell him about the hills of Alfama — you looked back once too','Falar-lhe das colinas de Alfama — tu também olhaste uma vez para trás'),fx:()=>{addTrust('p8_lobsang',2);stat('saud',2)},
   next:out(t('他听完，点点头，说了一句藏语。次仁想了想才翻译：“他说你的山不高，可是你回来还能看见。这就够了。”','He listens, nods and says something in Tibetan. Tsering thinks before she translates. "He says your hill isn\'t high, but you can still go back and see it. That\'s enough."','Ouve, acena e diz qualquer coisa em tibetano. A Tsering pensa antes de traduzir. «Diz que a tua colina não é alta, mas ainda podes voltar e vê-la. Isso chega.»'),SUM('洛桑爷爷信任 +2 · 乡愁 +2','Grandpa Lobsang trust +2 · Homesickness +2','Confiança do avô Lobsang +2 · Saudade +2'))},
  {t:t('问他走的时候带了什么','Ask what he carried when he left','Perguntar o que levou quando partiu'),fx:()=>{addTrust('p8_lobsang',1);addTrust('p8_tsering',1)},
   next:out(t('他进屋拿出一只木碗，边上磨得发亮。“这个，一串念珠，一双鞋。鞋在路上走坏了。”他把碗递给次仁，“以后是你的。”次仁没有用英语回答。','He goes inside and brings out a wooden bowl, its rim worn smooth. "This, a string of beads, and a pair of shoes. The shoes wore out on the way." He hands the bowl to Tsering. "One day it\'s yours." Tsering doesn\'t answer in English.','Entra em casa e traz uma tigela de madeira, com a borda polida pelo uso. «Isto, um fio de contas e um par de sapatos. Os sapatos gastaram-se pelo caminho.» Dá a tigela à Tsering. «Um dia é tua.» A Tsering não responde em inglês.'),SUM('洛桑爷爷、次仁信任 +1','Grandpa Lobsang and Tsering trust +1','Confiança do avô Lobsang e da Tsering +1'))},
  {t:t('给他看手机里里斯本的河','Show him the river in Lisbon on your phone','Mostrar-lhe o rio de Lisboa no telemóvel'),fx:()=>{addLike('p8_lobsang',1);stat('saud',1)},
   next:out(t('他凑得很近，看了很久那片宽宽的、发亮的河面。“水往海里去，”他说，“都往一个地方去。”','He leans in close and looks a long time at the wide, shining river. "Water goes to the sea," he says. "It all goes to one place."','Aproxima-se muito e olha muito tempo para o rio largo e brilhante. «A água vai para o mar», diz. «Vai toda para o mesmo sítio.»'),SUM('洛桑爷爷好感 +1 · 乡愁 +1','Grandpa Lobsang affection +1 · Homesickness +1','Afeto do avô Lobsang +1 · Saudade +1'))}]),
 ()=>sc(t('风马旗','Prayer flags','Bandeiras de oração'),'',[
  t('洛桑爷爷把一串旧的风马旗交到你手里，蓝、白、红、绿、黄，五种颜色，边都被韦科的太阳晒得发白了。','Grandpa Lobsang puts a string of old prayer flags into your hands: blue, white, red, green, yellow, their edges bleached by the Waco sun.','O avô Lobsang põe-te nas mãos um fio de bandeiras de oração velhas: azul, branco, vermelho, verde, amarelo, com as bordas desbotadas pelo sol de Waco.'),
  t('次仁翻译：“他说，挂在你店门口。风吹一次，就替你念一次。你忙得没空想家的时候，风替你想。”','Tsering translates. "He says hang them outside your shop. Every time the wind blows, it says a prayer for you. When you\'re too busy to miss home, the wind will miss it for you."','A Tsering traduz. «Diz para as pendurares à porta do restaurante. Cada vez que o vento sopra, reza por ti. Quando estiveres ocupado de mais para ter saudades, o vento tem-nas por ti.»')],[
  {t:t('挂在店门口，答应节上也挂一串','Hang them outside the shop, and promise a string for the festival too','Pendurá-las à porta e prometer um fio também para a festa'),fx:()=>{addTrust('p8_lobsang',1);stat('saud',1);S.flags.p8_lobsangFest=1},
   next:out(t('风马旗挂在若泽的旧招牌下面，在德州的风里一直飘。厄尔路过，抬头看了半天：“这是哪个球队的？”','The flags hang under José\'s old sign and flutter all day in the Texas wind. Earl walks past and squints up at them a long while. "Which team is this?"','As bandeiras ficam por baixo da tabuleta velha do José e esvoaçam o dia todo ao vento do Texas. O Earl passa e fica muito tempo a olhar. «Isto é de que equipa?»'),SUM('洛桑爷爷会为圣安东尼节祝福 · 乡愁 +1','Grandpa Lobsang will bless the festival · Homesickness +1','O avô Lobsang vai abençoar a festa · Saudade +1'))},
  {t:t('拆下一面，寄给里斯本的妈妈','Take one flag and post it to your mother in Lisbon','Tirar uma bandeira e mandá-la à tua mãe em Lisboa'),fx:()=>{addTrust('p8_lobsang',2);stat('saud',2)},
   next:out(t('一个礼拜后，妈妈发来一张照片：那面蓝色的小旗子挂在阿尔法马的阳台上，旁边是一盆罗勒。“风也替我想你了，”她写道。','A week later your mother sends a photo: the little blue flag hanging on a balcony in Alfama, next to a pot of basil. "The wind misses you for me too," she writes.','Uma semana depois a tua mãe manda uma fotografia: a bandeirinha azul pendurada numa varanda de Alfama, ao lado de um manjerico. «O vento também tem saudades tuas por mim», escreve.'),SUM('洛桑爷爷信任 +2 · 乡愁 +2','Grandpa Lobsang trust +2 · Homesickness +2','Confiança do avô Lobsang +2 · Saudade +2'))},
  {t:t('请他为圣安东尼节念一段祝福','Ask him to say a blessing for the Santo António festival','Pedir-lhe que diga uma bênção para a festa de Santo António'),fx:()=>{addTrust('p8_lobsang',1);S.flags.p8_lobsangFest=1},
   next:out(t('他想了很久，问次仁圣安东尼是做什么的。“找丢了的东西。”老人点点头，好像这个答案他很满意：“那我去。”','He thinks for a long time and asks Tsering what Saint Anthony does. "Finds lost things." The old man nods, as if that answer pleases him. "Then I\'ll come."','Pensa muito tempo e pergunta à Tsering o que faz o Santo António. «Encontra as coisas perdidas.» O velho acena, como se a resposta lhe agradasse. «Então eu vou.»'),SUM('洛桑爷爷会为圣安东尼节祝福','Grandpa Lobsang will bless the festival','O avô Lobsang vai abençoar a festa'))}])
];
const lobsangChat=[
 [t('洛桑爷爷在院子里晒酥油，旁边放着一台收音机，放的是德州的乡村音乐台。他说他喜欢那个唱歌的人的叹气。','Grandpa Lobsang is setting butter out in the yard, a radio beside him tuned to a Texas country station. He says he likes the way the singer sighs.','O avô Lobsang está a pôr manteiga ao sol no quintal, com um rádio ao lado sintonizado numa estação de música country do Texas. Diz que gosta da maneira como o cantor suspira.'),()=>{stat('saud',1)},t('乡愁 +1','Homesickness +1','Saudade +1')],
 [t('他把转经筒递给你，教你顺时针转。你转了三圈，他点点头，又把转经筒拿了回去。','He hands you the prayer wheel and shows you to turn it clockwise. You turn it three times; he nods and takes it back.','Passa-te a roda de oração e mostra-te como girá-la no sentido dos ponteiros do relógio. Dás três voltas; ele acena e volta a ficar com ela.'),null,'']
];

/* ================= the place in Waco ================= */
const tea={id:'p8_tea',n:t('在院子里喝一碗酥油茶','A bowl of butter tea in the yard','Uma tigela de chá de manteiga no quintal'),cost:1,tip:t('每天一次 · 精力 +2 · 乡愁 +1','Once a day · Energy +2 · Homesickness +1','Uma vez por dia · Energia +2 · Saudade +1'),
 req:()=>!MET('p8_tenzin')&&!MET('p8_lobsang')?t('先认识这一家人','Meet the family first','Conhece primeiro a família'):S.flags.p8_teaD===DAY()?t('今天已经喝过了','Already had a bowl today','Já bebeste hoje'):true,
 run:()=>{S.flags.p8_teaD=DAY();S.energy=Math.min(10,S.energy+2);stat('saud',1);
  return say(t('酥油茶','Butter tea','Chá de manteiga'),pick([t('咸的，热的，有点油。你已经习惯了，甚至有点想念。院子里的风马旗被风吹得哗哗响。','Salty, hot, a little greasy. You\'re used to it now; you even miss it a little. The prayer flags in the yard snap in the wind.','Salgado, quente, um pouco gorduroso. Já te habituaste; até sentes um pouco a falta. As bandeiras de oração do quintal estalam ao vento.'),t('卓玛往你碗里多加了一勺酥油：“开车的人要多喝一点。”','Dolma adds an extra spoonful of butter to your bowl. "People who drive need more."','A Dolma junta mais uma colher de manteiga à tua tigela. «Quem conduz precisa de mais.»')]),t('精力 +2 · 乡愁 +1','Energy +2 · Homesickness +1','Energia +2 · Saudade +1'))}};
// story files load in file-name order and Waco is defined later (tx2.js, Object.assign(CITIES,…)), so attach the place
// when Waco is registered: a one-shot setter on CITIES.waco that turns back into a plain property.
const P8_YARD={id:'p8_yard',n:t('城南的小院和周末市集','A little yard on the south side & the weekend market','Um quintal no lado sul e a feira de fim de semana'),acts:[
 arc('tenzin',t('去市集找丹增','Find Tenzin at the market','Procurar o Tenzin na feira'),t('三段故事 · 每次来韦科一段','Three-part story · one part per visit to Waco','História em três partes · uma por visita a Waco'),[1,10,20],tenzin,tenzinChat),
 arc('dolma',t('去画室看卓玛画画','Watch Dolma paint','Ver a Dolma pintar'),t('三段故事 · 每次来韦科一段','Three-part story · one part per visit to Waco','História em três partes · uma por visita a Waco'),[3,12,24],dolma,dolmaChat),
 arc('tsering',t('和次仁聊聊','Talk with Tsering','Falar com a Tsering'),t('三段故事 · 每次来韦科一段','Three-part story · one part per visit to Waco','História em três partes · uma por visita a Waco'),[5,14,28],tsering,tseringChat),
 arc('lobsang',t('陪洛桑爷爷坐一会儿','Sit with Grandpa Lobsang','Ficar um bocado com o avô Lobsang'),t('三段故事 · 每次来韦科一段','Three-part story · one part per visit to Waco','História em três partes · uma por visita a Waco'),[1,16,30],lobsang,lobsangChat),
 tea]};
const p8_attach=c=>{if(c&&Array.isArray(c.locs)&&!c.locs.some(l=>l.id==='p8_yard'))c.locs.push(P8_YARD)};
if(CITIES.waco)p8_attach(CITIES.waco);
else Object.defineProperty(CITIES,'waco',{configurable:true,enumerable:false,get(){return undefined},
 set(v){Object.defineProperty(CITIES,'waco',{value:v,writable:true,configurable:true,enumerable:true});p8_attach(v)}});

/* ================= Losar (Tibetan New Year), weeks 35–37 ================= */
const met=()=>['p8_tenzin','p8_dolma','p8_tsering','p8_lobsang'].filter(MET).length;
STORY.push({id:'p8_losar',when:()=>!S.where&&S.week>=35&&S.week<=37&&S.slot===0&&met()>=2,run:()=>sc(t('洛萨','Losar','Losar'),t('藏历新年','Tibetan New Year','Ano Novo tibetano'),[
 t('一大早，次仁打来电话：“今天是洛萨，我们的新年。爷爷说，去年这个时候家里多了一个朋友，今年要请他来。”','First thing in the morning Tsering calls. "Today\'s Losar, our New Year. Grandpa says this time last year the family didn\'t have you, and this year he wants you here."','Logo de manhã a Tsering telefona. «Hoje é o Losar, o nosso Ano Novo. O avô diz que no ano passado a família ainda não te tinha, e este ano quer que venhas.»'),
 t('“妈妈在炸卡赛，就是新年的油炸点心。爸爸包了三百个馍馍。爷爷在院子里换新的风马旗，旧的要等风吹散了才算完。”','"Mom\'s frying khapse, the New Year pastries. Dad\'s made three hundred momos. Grandpa\'s putting up new prayer flags in the yard — the old ones only count as finished once the wind has worn them away."','«A mãe está a fritar khapse, os bolinhos do Ano Novo. O pai fez trezentos momos. O avô está a pôr bandeiras novas no quintal — as velhas só contam como acabadas quando o vento as gasta.»')],[
 {t:t('[精力 2] 关店一晚，开车去韦科过年','[Energy 2] Close for the evening and drive to Waco for the New Year','[Energia 2] Fechar à noite e ir a Waco para o Ano Novo'),req:()=>S.energy>=2||NEED(t('精力 2','Energy 2','Energia 2')),fx:()=>{S.flags.p8_losar='went';S.energy=Math.max(0,S.energy-2);stat('saud',3);['p8_tenzin','p8_dolma','p8_tsering','p8_lobsang'].forEach(k=>{if(MET(k))addTrust(k,1)});S.lusoThisWeek=true},
  next:out(t('你带去了一盒蛋挞和一瓶波特酒。洛桑爷爷在院子里点了一堆小火，往里面撒了一把糌粑，说是给新的一年。次仁把你和全家人拍在一张照片里，照片背面写着三种文字。','You bring a box of custard tarts and a bottle of port. In the yard Grandpa Lobsang lights a small fire and scatters a handful of roasted barley flour into it — for the new year, he says. Tsering takes one photo of you with the whole family, and writes on the back in three scripts.','Levas uma caixa de pastéis de nata e uma garrafa de vinho do Porto. No quintal, o avô Lobsang acende uma pequena fogueira e espalha-lhe por cima um punhado de farinha de cevada torrada — para o ano novo, diz. A Tsering tira uma fotografia tua com a família toda e escreve nas costas em três alfabetos.'),t('乡愁 +3 · 精力 −2 · 这一家人信任 +1','Homesickness +3 · Energy −2 · the family\'s trust +1','Saudade +3 · Energia −2 · confiança da família +1'))},
 {t:t('[$20] 托丘伊的卡车捎一盒蛋挞过去','[$20] Send a box of custard tarts up with Chuy\'s truck','[$20] Mandar uma caixa de pastéis de nata no camião do Chuy'),req:MONEY(20),fx:()=>{S.flags.p8_losar='tarts';S.cash-=20;['p8_tenzin','p8_dolma','p8_tsering','p8_lobsang'].forEach(k=>{if(MET(k))addLike(k,1)})},
  next:out(t('晚上，次仁发来一段视频：洛桑爷爷把一个蛋挞掰成四份，全家一人一份，他自己那份蘸了酥油茶。','In the evening Tsering sends a video: Grandpa Lobsang splits a custard tart into four, one piece each, and dips his own in butter tea.','À noite a Tsering manda um vídeo: o avô Lobsang divide um pastel de nata em quatro, um pedaço para cada um, e molha o dele no chá de manteiga.'),t('这一家人好感 +1 · −$20','The family\'s affection +1 · −$20','Afeto da família +1 · −$20'))},
 {t:t('打个视频电话拜年','Video-call to wish them a happy New Year','Fazer uma videochamada para desejar bom ano'),fx:()=>{S.flags.p8_losar='call';stat('saud',1)},
  next:out(t('屏幕里人挤人，所有人同时在说话。最后是洛桑爷爷凑到镜头前，看了你很久，说了一句英语：“新年好。明年来。”','The screen is crowded, everyone talking at once. At the end Grandpa Lobsang leans into the camera, looks at you a long time and says, in English, "Happy New Year. Next year, come."','O ecrã está cheio, todos a falar ao mesmo tempo. No fim, o avô Lobsang aproxima-se da câmara, olha muito tempo para ti e diz, em inglês: «Feliz Ano Novo. Para o ano, vem.»'),t('乡愁 +1','Homesickness +1','Saudade +1'))}])});

/* ================= the festival (week 46) ================= */
const fest=()=>[S.flags.p8_lobsangFest&&['lobsang',S.flags.p4_wuFest?t('洛桑爷爷的风马旗挂在主街上空，就在美玲的红灯笼旁边，一串五色，一串红色，风一吹，一起响。','Grandpa Lobsang\'s prayer flags are strung over Main Street right beside Meiling\'s red lanterns, a line of five colours and a line of red, rustling together in the wind.','As bandeiras de oração do avô Lobsang estão penduradas sobre a rua principal, mesmo ao lado das lanternas vermelhas da Meiling, um fio de cinco cores e um fio vermelho, a sussurrar juntos ao vento.'):t('洛桑爷爷的风马旗挂在主街上空，五种颜色，在德州的风里一直飘。','Grandpa Lobsang\'s prayer flags are strung over Main Street, five colours fluttering in the Texas wind.','As bandeiras de oração do avô Lobsang estão penduradas sobre a rua principal, cinco cores a esvoaçar ao vento do Texas.')],
 S.flags.p8_dolmaFest&&['dolma',t('卓玛画的幡挂在教堂门口：一本书、一个孩子、一盆罗勒，没有画圣人的脸。阿尔贝蒂娜太太说，这样每个人都能把自己的圣人想进去。','Dolma\'s banner hangs at the church door: a book, a child, a pot of basil, and no saint\'s face. Dona Albertina says that way everyone can imagine their own saint into it.','O estandarte da Dolma está à porta da igreja: um livro, uma criança, um manjerico, e nenhuma cara de santo. A Dona Albertina diz que assim cada um pode lá pôr o seu santo.')],
 S.flags.p8_tenzinFest&&['tenzin',t('丹增从韦科拉来两大箱馍馍和一摞蒸笼，摊位就摆在你的烤架旁边，白汽和炭烟混在一起。','Tenzin drives down from Waco with two big crates of momos and a stack of steamers, setting up right next to your grill; the steam and the charcoal smoke mix.','O Tenzin vem de Waco com duas caixas grandes de momos e uma pilha de cestos de vapor, e monta a banca mesmo ao lado da tua grelha; o vapor e o fumo do carvão misturam-se.')],
 S.flags.p8_tseringFest&&['tsering',t('次仁背着相机来回跑，说她的毕业专题终于有结尾了。','Tsering runs back and forth with her camera, saying her capstone finally has an ending.','A Tsering anda de um lado para o outro com a máquina fotográfica, a dizer que o projeto final finalmente tem um fim.')]].filter(Boolean);
STORY.push({id:'p8_fest',when:()=>!S.where&&S.week===46&&S.day===1&&S.slot===1&&fest().length>0,run:()=>{const f=fest(),n=f.length;
 return sc(t('从韦科来的一家人','The family from Waco','A família de Waco'),t('圣安东尼节前两周','Two weeks before Santo António','Duas semanas antes do Santo António'),[
  t('节前两周，一辆旧车从韦科开来，停在你店门口。','Two weeks before the festival, an old car drives down from Waco and parks outside your shop.','Duas semanas antes da festa, um carro velho vem de Waco e estaciona à porta do restaurante.'),...f.map(x=>x[1]),
  t('洛桑爷爷站在你的店门口，看了很久主街两边的旗子和灯笼，说了一句藏语。次仁翻译：“他说，这里的山也不高。可是这里的人，把旗子挂得很高。”','Grandpa Lobsang stands at your door and looks a long time at the flags and lanterns along Main Street, then says something in Tibetan. Tsering translates: "He says the mountains here aren\'t high either. But the people here hang their flags high."','O avô Lobsang fica à tua porta a olhar muito tempo para as bandeiras e as lanternas ao longo da rua principal, e diz qualquer coisa em tibetano. A Tsering traduz: «Diz que aqui as montanhas também não são altas. Mas as pessoas daqui penduram as bandeiras bem alto.»')],[
  {t:t('请全家留下来吃晚饭','Ask the whole family to stay for dinner','Convidar a família toda para jantar'),fx:()=>{if(typeof c4_fs==='function')c4_fs(Math.min(2,n),'p8');stat('saud',1)},next:out(t('丹增吃了你的烤沙丁鱼，你吃了他的馍馍。最后大家一致同意：都比卡车司机说的好吃。','Tenzin eats your grilled sardines; you eat his momos. In the end everyone agrees: both are better than the truckers say.','O Tenzin come as tuas sardinhas assadas; tu comes os momos dele. No fim todos concordam: ambos são melhores do que os camionistas dizem.'),t('节日筹备上升 · 乡愁 +1','Festival prep up · Homesickness +1','Preparação da festa sobe · Saudade +1'))},
  {t:t('陪洛桑爷爷在门口多站一会儿','Stand in the doorway a little longer with Grandpa Lobsang','Ficar mais um bocado à porta com o avô Lobsang'),fx:()=>{if(typeof c4_fs==='function')c4_fs(Math.min(2,n),'p8');stat('saud',2)},next:out(t('风吹过主街，旗子哗哗地响。他转着转经筒，你什么也没说。你觉得，风真的在替你想家。','The wind comes down Main Street and the flags snap. He turns his prayer wheel; you say nothing. It feels as if the wind really is missing home for you.','O vento desce a rua principal e as bandeiras estalam. Ele gira a roda de oração; tu não dizes nada. Parece mesmo que o vento tem saudades por ti.'),t('节日筹备上升 · 乡愁 +2','Festival prep up · Homesickness +2','Preparação da festa sobe · Saudade +2'))}])}});

/* ================= one ending paragraph ================= */
{const p8_end0=ENDING_EXTRA;ENDING_EXTRA=ch=>{const o=p8_end0(ch);
 if(fest().length>=2)o.push(t('若泽烧烤店的门口一直挂着一串风马旗，旧了就换新的。每年洛萨，你都开车去韦科；每年圣安东尼节，一辆旧车从韦科开下来。','A string of prayer flags always hangs outside Zé\'s Churrasco, replaced when the old one wears out. Every Losar you drive up to Waco; every Santo António, an old car drives down from Waco.','À porta da Churrasqueira do Zé há sempre um fio de bandeiras de oração, trocado quando o velho se gasta. Em cada Losar vais de carro a Waco; em cada Santo António, um carro velho desce de Waco.'));
 return o}}
})();
